<?php require_once __DIR__.'/../../includes/bootstrap.php';$u=require_login();$pageTitle='My Bookings';$s=db()->prepare('SELECT * FROM vw_booking_summary WHERE user_id=? ORDER BY created_at DESC');$s->execute([$u['id']]);$rows=$s->fetchAll();$ns=db()->prepare('SELECT COUNT(*) FROM notifications WHERE user_id=? AND is_read=0');$ns->execute([$u['id']]);$userUnreadNotifications=(int)$ns->fetchColumn();require __DIR__.'/../../includes/header.php';?><div class="admin-shell user-shell"><aside class="sidebar"><?php require __DIR__ . '/../sidebar.php'; ?></aside><section class="admin-content user-content"><section class="page-hero"><div class="container"><div class="eyebrow">Private workspace</div><h1 class="page-title">My bookings.</h1><p>View the status and details of your event requests.</p></div></section><section class="section"><div class="container panel table-wrap"><div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:18px"><h2 style="font-size:34px">Booking history</h2><a class="btn btn-gold" href="<?=url('user/bookings/create.php?fresh=1')?>">+ New booking</a></div><table class="table"><thead><tr><th>Reference</th><th>Event</th><th>Venue</th><th>Date</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $b):?><tr><td><?=e($b['booking_ref'])?></td><td><b><?=e($b['event_title'])?></b></td><td><?=e($b['other_venue_name'] ?: ($b['venue_names']??'—'))?></td><td><?=date('d M Y H:i',strtotime($b['start_at']))?></td><td><span class="badge <?=$b['status']==='confirmed'?'badge-green':($b['status']==='rejected'?'badge-red':'badge-gold')?>"><?=e(ucwords(str_replace('_',' ',$b['status'])))?></span></td><td><a class="btn btn-outline btn-sm" style="color:var(--forest);border-color:#bbb" href="<?=url('user/bookings/view.php?id='.$b['id'])?>">View</a></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="6">No bookings found.</td></tr><?php endif;?></tbody></table></div></section></section></div><?php require __DIR__.'/../../includes/footer.php'; ?>
